syntax:
template<typename T1, typename T2, ..., typename Tn>
ReturnType function_name(parameter_list) {
    // function implementation
}

// For algorithms with predicate:
template<typename ForwardIterator, typename BinaryPredicate>
ForwardIterator algorithm_name(ForwardIterator first, ForwardIterator last, BinaryPredicate pred);

code_example:
#include <vector>
#include <algorithm>
#include <iostream>

int main() {
    std::vector<int> data = {1, 2, 2, 3, 4, 4, 5};
    auto pred = [](int a, int b) { return a == b; };
    auto it = std::adjacent_find(data.begin(), data.end(), pred);
    if (it != data.end()) {
        std::cout << "Found adjacent equal elements: " << *it << " and " << *(it + 1) << std::endl;
    } else {
        std::cout << "No adjacent equal elements found." << std::endl;
    }
    return 0;
}
